Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original MS C++ code you have to rewrite:
<original_code>
#include<iostream>
#include<stdio.h>
#include<string.h>
#include<cstring>
#include<string>
#include<algorithm>
#include<queue>
#include<map>
#include<set>
#include<cstdlib>
using namespace std;
#define fre1     freopen("in.txt","r",stdin)
#define fre2     freopen("out.txt","w",stdout)
const int maxn=200;
const int maxm=100000;
const int inf=199999999;
int ma[20][20];
int mat[maxn][maxn];
int n,N,t;
string s;
int hu[maxn][3];
int re[maxn][3];
int zr,zc;
int cx,cy;
int stran[4][2]={0,-1,0,1,-1,0,1,0};

int  isok(int r,int c){
	if(r>0&&r<=n&&c>0&&c<=n&&ma[r][c]!=-1){
		return (r-1)*n+c;
	}
	return -1;
}

void BG(){
	N=n*n;
	memset(mat,-1,sizeof(mat));
	for(int r1=1;r1<=n;r1++){
		for(int c1=1;c1<=n;c1++){
			if(ma[r1][c1]==-1)continue;
			int p1=(r1-1)*n+c1;
			mat[p1][p1]=0;
			for(int i=0;i<4;i++){
				int r2=r1+stran[i][0];
				int c2=c1+stran[i][1];
				if(r2>0&&r2<=n&&c2>0&&c2<=n&&ma[r2][c2]!=-1){
					int p2=(r2-1)*n+c2;	
					mat[p1][p2]=1;
				}
			}	
		}
	}
}
int dis[maxn];
int qu[maxm];
int inq[maxn];
void spfa(){
	int fr=0;
	int re=1;
	for(int i=1;i<=N;i++)dis[i]=inf;
	int dd=(zr-1)*n+zc;
	dis[dd]=0;
	qu[0]=dd;
	while(fr<re){
		int now=qu[fr++];
		for(int i=1;i<=N;i++){
			if(mat[now][i]==1&&dis[i]>dis[now]+1){
				dis[i]=dis[now]+1;
				qu[re++]=i;
			}
		}
	}
}
void Floyd(){
	for(int i=1;i<=N;i++){
		for(int j=1;j<=N;j++){
			for(int z=1;z<=N;z++){
				if(mat[j][i]!=-1&&mat[i][z]!=-1){
					if(mat[j][z]==-1||mat[j][z]>mat[j][i]+mat[i][z]){
						mat[j][z]=mat[j][i]+mat[i][z];
					}
				}
			}
		}
	}
}
struct Edge{
	int st,ed,flow,next;
}edge[maxm];
int head[maxn];
int E;
int src,dest;
void addedge(int st,int ed,int flow){
	edge[E].st=st; edge[E].ed=ed; edge[E].flow=flow; edge[E].next=head[st];
	head[st]=E++;
	edge[E].st=ed; edge[E].ed=st; edge[E].flow=0;edge[E].next=head[ed];
	head[ed]=E++;
}
void BF(){
	memset(head,-1,sizeof(head));
	E=0;
	src=0;
	dest=cx+cy+1;
	for(int i=1;i<=cx;i++){
		addedge(src,i,hu[i][2]);
	}
	for(int i=1;i<=cy;i++){
		addedge(cx+i,dest,re[i][2]);
	}
	int dd=(zr-1)*n+zc;
	for(int i=1;i<=cx;i++){
		for(int j=1;j<=cy;j++){
			int p1=(hu[i][0]-1)*n+hu[i][1];
			int p2=(re[j][0]-1)*n+re[j][1];
			if(mat[p1][p2]!=-1&&mat[p1][p2]<=t&&mat[p1][p2]<dis[p2]){
				addedge(i,cx+j,inf);
			}
			else if(mat[p1][p2]!=-1&&mat[p1][p2]<=t&&mat[p1][p2]==dis[p2]){
				for(int z=0;z<4;z++){
						int rr=re[j][0]+stran[z][0];
						int cc=re[j][1]+stran[z][1];
						int pp=isok(rr,cc);
						if(pp!=-1){
							if(mat[p1][pp]==mat[p1][p2]-1&&mat[p1][pp]<dis[pp]){
								addedge(i,cx+j,inf);
							}
						}
				}
			}
		}
	}
}
int  d[maxn];
bool dinic_bfs(){
	int que[maxn];
	int front=0;
	int rear=1;
	que[0]=src;
	memset(d,-1,sizeof(d));
	d[src]=0;
	while(front<rear){
		int now=que[front++];
		for(int i=head[now];i!=-1;i=edge[i].next){
			int ed=edge[i].ed;
			if(d[ed]==-1&&edge[i].flow>0){
				d[ed]=d[now]+1;
				if(ed==dest)return d[dest]>=0;
				que[rear++]=ed;
			}
		}
	}
	return 0;
}
int stk[maxn];
int cur[maxn];
int  dinic(){
	int ret=0;
	int minf,i;
	while(dinic_bfs()){
		int u=src,tail=0;
		for( i=src;i<=dest;i++)cur[i]=head[i];//for(i=0;i<=n+1;i++)cur[i]=head[i];
		while(cur[src]!=-1){
			if(u!=dest&&cur[u]!=-1&&edge[cur[u]].flow>0&&d[u]!=-1
				&&d[u]+1==d[edge[cur[u]].ed]){
				stk[tail++]=cur[u];
				u=edge[cur[u]].ed;
			}
			else if(u==dest){
				for(minf=inf,i=tail-1;i>=0;i--){
					if(edge[stk[i]].flow<minf)minf=edge[stk[i]].flow;
				}
				for(ret+=minf,i=tail-1;i>=0;i--){
					edge[stk[i]].flow-=minf;
					edge[stk[i]^1].flow+=minf;
					if(edge[stk[i]].flow==0)tail=i;
				}
				u=edge[stk[tail]].st;
			}
			else{
				while(tail>0&&u!=src&&cur[u]==-1)u=edge[stk[--tail]].st;
				cur[u]=edge[cur[u]].next;
			}
		}
	}
	return ret;
}

int solve(){
	ma[zr][zc]=0;
	BG();
	spfa();
	ma[zr][zc]=-1;
	BG();
	Floyd();
	BF();
	int ret=dinic();
	return ret;
}



int main(){
	cin>>n>>t;
	cx=cy=0;
	memset(ma,0,sizeof(ma));
	for(int i=1;i<=n;i++){
		cin>>s;
		for(int j=0;j<n;j++){
			if(s[j]=='Y')ma[i][j+1]=-1;
			else if(s[j]=='Z'){
				zr=i; zc=j+1;
				ma[i][j+1]=-1;
			}
			else if(s[j]>'0'&&s[j]<='9'){
				hu[++cx][0]=i;
				hu[cx][1]=j+1;
				hu[cx][2]=s[j]-'0';
			}
		}
	}
	for(int i=1;i<=n;i++){
		cin>>s;
		for(int j=0;j<n;j++){
			if(s[j]>'0'&&s[j]<='9'){
				re[++cy][0]=i;
				re[cy][1]=j+1;
				re[cy][2]=s[j]-'0';
			}
		}
	}
	cout<<solve()<<endl;
	return 0;
}
